<?php
if (!defined('PORTAL_VIEW_ROUTER')) {http_response_code(403);exit;}
$myScore=one("SELECT (SELECT COALESCE(SUM(t.points),0) FROM tasks t JOIN (SELECT DISTINCT task_id FROM submissions WHERE user_id=? AND status='passed') s ON s.task_id=t.id) + (SELECT COALESCE(SUM(e.points),0) FROM attendances a JOIN events e ON e.id=a.event_id WHERE a.user_id=?) total",[$u['id'],$u['id']]);
$fields=['full_name'=>'Họ và tên','student_id'=>'MSSV','class_number'=>'Số thứ tự trong lớp','class_name'=>'Lớp','dob'=>'Ngày sinh','card_number'=>'Số thẻ Đoàn viên (đã xác minh)','hometown'=>'Quê quán','gender'=>'Giới tính','ethnic_group'=>'Dân tộc','religion'=>'Tôn giáo','phone'=>'Số điện thoại','email'=>'Email sinh viên','personal_email'=>'Email cá nhân','party_joined_date'=>'Ngày vào Đảng (nếu có)','joined_date'=>'Ngày vào Đoàn','activity_unit'=>'Nơi sinh hoạt Đoàn','position_title'=>'Chức vụ','membership'=>'Tình trạng Đoàn'];
$fill=count(array_filter(['full_name','student_id','dob','hometown','phone','email','joined_date','activity_unit'],fn($key)=>trim((string)($u[$key]??''))!==''));
title('Hồ sơ cá nhân','Quản lý thông tin, ảnh đại diện, câu nói và quyền riêng tư theo mô hình FocusBrain.');
echo '<section class="panel profile-hero"><div class="profile-head"><div class="profile-avatar">';
if($u['avatar_path'])echo '<img alt="Ảnh đại diện" src="index.php?page=avatar&id='.(int)$u['id'].'">';else echo '<span>'.e(mb_substr($u['full_name'],0,1)).'</span>';
echo '</div><div><h2>'.e($u['full_name']).'</h2><div class="muted">'.e($u['student_id']).' · '.e($u['class_name']??'').'</div><blockquote>“'.e($u['quote_text']?:'Mỗi ngày một hành động tích cực.').'” — '.e($u['quote_author']?:'').'</blockquote></div></div><div class="stats"><article><small>Điểm tích lũy</small><strong>'.(int)($myScore['total']??0).'</strong></article><article><small>Hồ sơ cơ bản</small><strong>'.$fill.'/8</strong></article><article><small>Xác minh thẻ</small><strong>'.($u['card_verified_at']?'Đã duyệt':'Chưa').'</strong></article></div></section>';
panel('Thông tin hồ sơ');echo '<div class="profile-field-grid">';foreach($fields as $k=>$label){$v=$u[$k]??null;$display=$v?:'Chưa cập nhật';if(in_array($k,['dob','joined_date','party_joined_date'],true)&&$v)$display=date('d/m/Y',strtotime($v));echo '<div><small>'.e($label).'</small><b>'.e($display).'</b></div>';}echo '</div><p class="muted">MSSV, họ tên, số thẻ và ngày vào Đoàn chỉ do cán bộ xác minh/cập nhật. Thông tin nhạy cảm chỉ hiển thị cho chủ tài khoản và admin có quyền.</p></section>';
panel('Tùy chỉnh cá nhân');form_open('save_profile');inputf('Số điện thoại','phone',$u['phone']??'','tel','maxlength="32"');inputf('Email cá nhân','personal_email',$u['personal_email']??'','email','maxlength="191"');inputf('Câu nói','quote_text',$u['quote_text']??'','text','maxlength="400"');inputf('Tác giả','quote_author',$u['quote_author']??'','text','maxlength="160"');inputf('Ảnh đại diện','avatar','','file','accept="image/jpeg,image/png,image/webp"');echo '<label class="choice"><input type="checkbox" name="leaderboard_visible" value="1" '.($u['leaderboard_visible']?'checked':'').'> Hiển thị tên tôi trên bảng xếp hạng</label>';submitf('Lưu thay đổi');echo '</section>';
panel('Bảo mật tài khoản');echo '<p>Email sinh viên dùng để đăng nhập: <b>'.e($u['email']).'</b></p><p>Google: '.($u['google_sub']?'Đã liên kết':'Chưa liên kết').'</p>';
if(!$u['google_sub']&&conf('google_client_id'))echo '<p><a href="index.php?page=google_start">Liên kết tài khoản Google →</a></p>';
form_open('change_password');inputf('Mật khẩu hiện tại','old_password','','password','required');inputf('Mật khẩu mới (≥12 ký tự)','new_password','','password','required minlength="12"');submitf('Đổi mật khẩu');echo '</section>';
